//! The integer codecs generated by `impl_sql_int_enum!`, over real Postgres.
//!
//! The discriminants are a wire format — already written into every deployed
//! SQLite database — so these tests pin the exact stored integer for every
//! variant, not just that a round-trip returns what went in. A round-trip alone
//! would still pass if a whole enum's numbering shifted.

use sqlx::Row;
use xmtp_db::consent_record::{ConsentState, ConsentType};
use xmtp_db::group::{ConversationType, GroupMembershipState};
use xmtp_db::group_intent::{IntentKind, IntentState};
use xmtp_db::group_message::{ContentType, DeliveryStatus, GroupMessageKind};
use xmtp_db::identity_cache::StoredIdentityKind;
use xmtp_db::processed_device_sync_messages::DeviceSyncProcessingState;
use xmtp_db::refresh_state::EntityKind;
use xmtp_db::remote_commit_log::CommitResult;
use xmtp_db_pg_tests::bare_db;

/// Binds `$value`, asserts Postgres stored exactly `$expected`, then reads the
/// column back as the enum and asserts it decodes to the original variant.
macro_rules! assert_stored_as {
    ($db:expr, $ty:ty, $value:expr, $expected:expr) => {{
        let mut conn = $db.conn().await.expect("connection");
        let row = sqlx::query("SELECT $1::int4 AS v")
            .bind($value)
            .fetch_one(&mut *conn)
            .await
            .expect("bind and select");

        let stored: i32 = row.try_get("v").expect("read back as i32");
        assert_eq!(
            stored, $expected,
            concat!(
                stringify!($ty),
                "::",
                stringify!($value),
                " must encode to the discriminant already stored in deployed databases",
            ),
        );

        let decoded: $ty = row.try_get("v").expect("decode as enum");
        assert_eq!(decoded, $value, "decode must invert encode");
    }};
}

#[tokio::test]
async fn consent_discriminants_round_trip() {
    let db = bare_db("enum_consent").await;
    assert_stored_as!(db, ConsentType, ConsentType::ConversationId, 1);
    assert_stored_as!(db, ConsentType, ConsentType::InboxId, 2);
    assert_stored_as!(db, ConsentState, ConsentState::Unknown, 0);
    assert_stored_as!(db, ConsentState, ConsentState::Allowed, 1);
    assert_stored_as!(db, ConsentState, ConsentState::Denied, 2);
}

#[tokio::test]
async fn group_discriminants_round_trip() {
    let db = bare_db("enum_group").await;
    assert_stored_as!(db, GroupMembershipState, GroupMembershipState::Allowed, 1);
    assert_stored_as!(db, GroupMembershipState, GroupMembershipState::Rejected, 2);
    assert_stored_as!(db, GroupMembershipState, GroupMembershipState::Pending, 3);
    assert_stored_as!(db, GroupMembershipState, GroupMembershipState::Restored, 4);
    assert_stored_as!(
        db,
        GroupMembershipState,
        GroupMembershipState::PendingRemove,
        5
    );

    assert_stored_as!(db, ConversationType, ConversationType::Group, 1);
    assert_stored_as!(db, ConversationType, ConversationType::Dm, 2);
    assert_stored_as!(db, ConversationType, ConversationType::Sync, 3);
    assert_stored_as!(db, ConversationType, ConversationType::Oneshot, 4);
}

