#[tokio::test]
async fn misc_discriminants_round_trip() {
    let db = bare_db("enum_misc").await;
    assert_stored_as!(db, StoredIdentityKind, StoredIdentityKind::Ethereum, 1);
    assert_stored_as!(db, StoredIdentityKind, StoredIdentityKind::Passkey, 2);

    assert_stored_as!(
        db,
        DeviceSyncProcessingState,
        DeviceSyncProcessingState::Pending,
        0
    );
    assert_stored_as!(
        db,
        DeviceSyncProcessingState,
        DeviceSyncProcessingState::Processed,
        1
    );
    assert_stored_as!(
        db,
        DeviceSyncProcessingState,
        DeviceSyncProcessingState::Failed,
        2
    );

    assert_stored_as!(db, EntityKind, EntityKind::Welcome, 1);
    assert_stored_as!(db, EntityKind, EntityKind::ApplicationMessage, 2);
    assert_stored_as!(db, EntityKind, EntityKind::CommitLogUpload, 3);
    assert_stored_as!(db, EntityKind, EntityKind::CommitLogDownload, 4);
    assert_stored_as!(db, EntityKind, EntityKind::CommitLogForkCheckLocal, 5);
    assert_stored_as!(db, EntityKind, EntityKind::CommitLogForkCheckRemote, 6);
    assert_stored_as!(db, EntityKind, EntityKind::CommitMessage, 7);

    assert_stored_as!(db, CommitResult, CommitResult::Unknown, 0);
    assert_stored_as!(db, CommitResult, CommitResult::Success, 1);
    assert_stored_as!(db, CommitResult, CommitResult::WrongEpoch, 2);
    assert_stored_as!(db, CommitResult, CommitResult::Undecryptable, 3);
    assert_stored_as!(db, CommitResult, CommitResult::Invalid, 4);
}

/// A value with no corresponding variant is rejected, not coerced to a default.
///
/// This is how a database written by a newer build surfaces after a downgrade;
/// silently mapping it onto an existing variant would corrupt state rather than
/// fail the read.
#[tokio::test]
async fn unknown_discriminant_is_rejected() {
    let db = bare_db("enum_unknown").await;
    let mut conn = db.conn().await.unwrap();
    let row = sqlx::query("SELECT 99::int4 AS v")
        .fetch_one(&mut *conn)
        .await
        .unwrap();

    let err = row
        .try_get::<ConsentState, _>("v")
        .expect_err("99 is not a ConsentState");
    let msg = err.to_string();
    assert!(
        msg.contains("Unrecognized ConsentState variant 99"),
        "error should name the type and the offending value, got: {msg}"
    );
}

/// Nullable enum columns decode through the same codec via sqlx's `Option`
/// wrapper — `NULL` must read as `None`, not as a zero-valued variant.
#[tokio::test]
async fn null_decodes_as_none() {
    let db = bare_db("enum_null").await;
    let mut conn = db.conn().await.unwrap();
    let row = sqlx::query("SELECT NULL::int4 AS v")
        .fetch_one(&mut *conn)
        .await
        .unwrap();

    let decoded: Option<ConsentState> = row.try_get("v").expect("NULL decodes");
    assert_eq!(decoded, None);
}
